key = Pin(14, Pin.IN, Pin.PULL_UP)    # 右鍵 KEY

import time
running = False; t0 = 0; acc = 0; laps = []
def fmt(ms): return '%02d:%02d.%d' % (ms // 60000, (ms // 1000) % 60, (ms // 100) % 10)
def draw(ms):
    d.fill(d.BLACK)
    d.text(fmt(ms), 45, 40, d.GREEN if running else d.WHITE)
    for i, l in enumerate(laps[-5:]): d.text('L%d %s' % (i + 1, fmt(l)), 30, 90 + i * 16, d.CYAN)
    d.text('KEY start/stop', 25, 280, d.YELLOW); d.text('BOOT lap/reset', 25, 296, d.YELLOW)
    d.show()
draw(0)
while lab.running():
    now = time.ticks_ms(); ms = acc + (time.ticks_diff(now, t0) if running else 0)
    if key.value() == 0:
        if running: acc = ms; running = False; print('暫停', fmt(ms))
        else: t0 = now; running = True; print('開始')
        draw(ms)
        while lab.running() and key.value() == 0: lab.sleep(0.02)
    if boot.value() == 0:
        if running: laps.append(ms); print('分段', fmt(ms))
        else: acc = 0; laps = []; print('歸零')
        draw(ms)
        while lab.running() and boot.value() == 0: lab.sleep(0.02)
    if running and (ms // 100) != ((ms - 20) // 100): draw(ms)
    lab.sleep(0.02)

import lab
from lab.board_tqt import color     # color(r, g, b) → 螢幕用的 RGB565
d = lab.display            # 板上 170×320 彩色螢幕
from machine import Pin
boot = Pin(0, Pin.IN, Pin.PULL_UP)    # 左鍵 BOOT：沒按=1，按下=0
key = Pin(14, Pin.IN, Pin.PULL_UP)    # 右鍵 KEY

import neopixel
np = neopixel.NeoPixel(Pin(16), 8)
modes = ['chase', 'rainbow', 'breathe']; mi = 0; t = 0
def wheel(p):
    p = p % 255
    if p < 85: return (255 - p * 3, p * 3, 0)
    if p < 170: p -= 85; return (0, 255 - p * 3, p * 3)
    p -= 170; return (p * 3, 0, 255 - p * 3)
while lab.running():
    if key.value() == 0:
        mi = (mi + 1) % 3; print('模式', modes[mi])
        while lab.running() and key.value() == 0: lab.sleep(0.02)
    m = modes[mi]
    for i in range(8):
        if m == 'chase': np[i] = (255, 60, 0) if i == t % 8 else (0, 0, 0)
        elif m == 'rainbow': np[i] = wheel(i * 32 + t * 8)
        else:
            b = (t % 40) if (t % 80) < 40 else 40 - (t % 40)
            np[i] = (0, b * 6, b * 3)
    np.write()
    d.fill(d.BLACK); d.text(m, 60, 150, d.WHITE); d.text('KEY: next', 45, 290, d.YELLOW); d.show()
    t += 1
    lab.sleep(0.08)
